-- 04 workforce: generated by database/tools/generate.py from database/model/. Do not edit.
-- may reference: catalog, core

CREATE SCHEMA IF NOT EXISTS workforce AUTHORIZATION spms_owner;

CREATE TABLE workforce.staff (
    staff_id                       uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    principal_id                   uuid,
    home_property_id               uuid,
    department_code                text,
    preferred_name                 text NOT NULL,
    employment_status              text NOT NULL DEFAULT 'Active',
    bookable                       boolean NOT NULL DEFAULT true,
    hris_system                    text,
    hris_worker_id                 text,
    payroll_system                 text,
    payroll_worker_id              text,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT staff_pkey PRIMARY KEY (staff_id),
    CONSTRAINT staff_employment_status_ck CHECK (employment_status IN ('Pending', 'Active', 'OnLeave', 'Suspended', 'Terminated')),
    CONSTRAINT staff_version_ck CHECK (version >= 1),
    CONSTRAINT staff_tenant_identity_uq UNIQUE (tenant_id, staff_id),
    CONSTRAINT staff_principal_uq UNIQUE (principal_id),
    CONSTRAINT staff_hris_uq UNIQUE (tenant_id, hris_system, hris_worker_id)
);
COMMENT ON TABLE workforce.staff IS 'Operational staff profile, broadly visible. Property membership comes from staff_role_assignment. [§Spa service provider and small HR module; §53.2 Staff management]';
COMMENT ON COLUMN workforce.staff.department_code IS 'code_list Department';

CREATE TABLE workforce.spa_service_provider (
    spa_service_provider_id        uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    staff_id                       uuid NOT NULL,
    employee_number                text NOT NULL,
    first_name                     text NOT NULL,
    middle_name                    text,
    last_name                      text NOT NULL,
    work_email                     text,
    personal_email                 text,
    mobile_phone                   text,
    home_address                   jsonb,
    worker_type                    text NOT NULL,
    job_title                      text NOT NULL,
    supervisor_staff_id            uuid,
    hire_date                      date,
    end_date                       date,
    languages                      text[] NOT NULL DEFAULT '{}',
    public_bio                     text,
    public_profile_consent         boolean NOT NULL DEFAULT false,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT spa_service_provider_pkey PRIMARY KEY (spa_service_provider_id),
    CONSTRAINT spa_service_provider_worker_type_ck CHECK (worker_type IN ('Employee', 'Contractor', 'Agency')),
    CONSTRAINT spa_service_provider_version_ck CHECK (version >= 1),
    CONSTRAINT spa_service_provider_tenant_identity_uq UNIQUE (tenant_id, spa_service_provider_id),
    CONSTRAINT spa_service_provider_dates_ordered CHECK (end_date IS NULL OR hire_date IS NULL OR end_date >= hire_date),
    CONSTRAINT spa_service_provider_staff_uq UNIQUE (staff_id),
    CONSTRAINT spa_service_provider_employee_number_uq UNIQUE (tenant_id, employee_number)
);
COMMENT ON TABLE workforce.spa_service_provider IS 'HR profile, 1:1 with staff but deliberately a separate table: the spec requires operational and employment data to be separable with category-specific access. [§What belongs on file; SEC-007; §24 Workforce records (separate operational and employment data)]';

CREATE TABLE workforce.staff_role_assignment (
    staff_role_assignment_id       uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid,
    staff_id                       uuid NOT NULL,
    role_code                      text NOT NULL,
    approved_by                    uuid,
    approved_at                    timestamptz,
    fga_synced_at                  timestamptz,
    status                         text NOT NULL DEFAULT 'Proposed',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT staff_role_assignment_pkey PRIMARY KEY (staff_role_assignment_id),
    CONSTRAINT staff_role_assignment_role_code_ck CHECK (role_code IN ('provider', 'front_desk', 'spa_manager', 'hr_compliance', 'finance', 'platform_admin', 'configuration_approver', 'scheduler', 'housekeeping', 'inventory_manager', 'marketing', 'support', 'operations_analyst', 'executive', 'release_manager', 'security_admin', 'integration_service')),
    CONSTRAINT staff_role_assignment_version_ck CHECK (version >= 1),
    CONSTRAINT staff_role_assignment_tenant_identity_uq UNIQUE (tenant_id, staff_role_assignment_id),
    CONSTRAINT staff_role_assignment_status_known CHECK (status IN ('Proposed', 'Active', 'Revoked', 'Expired')),
    CONSTRAINT staff_role_assignment_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT staff_role_assignment_active_is_approved CHECK (status <> 'Active' OR approved_by IS NOT NULL),
    CONSTRAINT staff_role_assignment_approver_not_proposer CHECK (approved_by IS NULL OR approved_by IS DISTINCT FROM created_by)
);
COMMENT ON TABLE workforce.staff_role_assignment IS 'Source of truth for OpenFGA role tuples. property_id NULL = tenant-wide role. [technical/config/role_permissions.json; security.assign_role:approved]';
COMMENT ON COLUMN workforce.staff_role_assignment.fga_synced_at IS 'set when the outbox worker confirms the tuple write';

CREATE TABLE workforce.credential (
    credential_id                  uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    staff_id                       uuid NOT NULL,
    credential_kind                text NOT NULL,
    license_type_code              text,
    jurisdiction                   text,
    issuer_name                    text,
    number_cipher                  bytea,
    number_key_version             text,
    number_last4                   char(4),
    provider_case_reference        text,
    consent_reference              text,
    adjudication                   text,
    issued_at                      date,
    expires_at                     date,
    verified_by                    uuid,
    verified_at                    timestamptz,
    evidence_document_id           uuid,
    restrictions                   text,
    status                         text NOT NULL DEFAULT 'Pending',
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT credential_pkey PRIMARY KEY (credential_id),
    CONSTRAINT credential_credential_kind_ck CHECK (credential_kind IN ('License', 'Certification', 'Training', 'BackgroundCheck')),
    CONSTRAINT credential_adjudication_ck CHECK (adjudication IN ('Eligible', 'NotEligible', 'ReviewRequired', 'Withdrawn')),
    CONSTRAINT credential_version_ck CHECK (version >= 1),
    CONSTRAINT credential_tenant_identity_uq UNIQUE (tenant_id, credential_id),
    CONSTRAINT credential_status_known CHECK (status IN ('Pending', 'Verified', 'Expired', 'Revoked', 'Rejected')),
    CONSTRAINT credential_cipher_has_key CHECK ((number_cipher IS NULL) = (number_key_version IS NULL)),
    CONSTRAINT credential_verified_complete CHECK (status <> 'Verified' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL)),
    CONSTRAINT credential_adjudication_only_screening CHECK (adjudication IS NULL OR credential_kind = 'BackgroundCheck'),
    CONSTRAINT credential_license_typed CHECK (credential_kind NOT IN ('License', 'Certification') OR license_type_code IS NOT NULL),
    CONSTRAINT credential_dates_ordered CHECK (expires_at IS NULL OR issued_at IS NULL OR expires_at >= issued_at)
);
COMMENT ON TABLE workforce.credential IS 'Licenses, certifications and background checks: each is a verified, expiring fact about a worker. [§Credential rules; §53.2 expiration alerts, screening status; DEC-006]';
COMMENT ON COLUMN workforce.credential.license_type_code IS 'code_list LicenseType';
COMMENT ON COLUMN workforce.credential.issuer_name IS 'licensing body, or screening provider';
COMMENT ON COLUMN workforce.credential.provider_case_reference IS 'screening provider case id';

CREATE TABLE workforce.staff_document (
    document_id                    uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    staff_id                       uuid NOT NULL,
    document_type                  text NOT NULL,
    object_reference               text NOT NULL,
    content_sha256                 char(64) NOT NULL,
    mime_type                      text NOT NULL,
    size_bytes                     bigint NOT NULL,
    malware_scan_status            text NOT NULL DEFAULT 'Pending',
    access_class                   text NOT NULL,
    retention_key                  text,
    expires_on                     date,
    acknowledged_at                timestamptz,
    status                         text NOT NULL DEFAULT 'Active',
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT staff_document_pkey PRIMARY KEY (document_id),
    CONSTRAINT staff_document_size_bytes_ck CHECK (size_bytes > 0),
    CONSTRAINT staff_document_malware_scan_status_ck CHECK (malware_scan_status IN ('Pending', 'Clean', 'Infected', 'Failed')),
    CONSTRAINT staff_document_access_class_ck CHECK (access_class IN ('Operational', 'Employment', 'Screening', 'Payroll')),
    CONSTRAINT staff_document_version_ck CHECK (version >= 1),
    CONSTRAINT staff_document_tenant_identity_uq UNIQUE (tenant_id, document_id),
    CONSTRAINT staff_document_status_known CHECK (status IN ('Active', 'Superseded', 'Expired'))
);
COMMENT ON TABLE workforce.staff_document IS 'Metadata only; the file lives in blob storage. [SEC-007; §53.2 document upload]';
COMMENT ON COLUMN workforce.staff_document.retention_key IS 'core.setting retention.<class>';

CREATE TABLE workforce.staff_qualification (
    qualification_id               uuid NOT NULL DEFAULT core.uuid_v7(),
