CREATE TABLE workforce.work_schedule (
    work_schedule_id               uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid NOT NULL,
    staff_id                       uuid NOT NULL,
    entry_type                     text NOT NULL,
    leave_type                     text,
    starts_at                      timestamptz NOT NULL,
    ends_at                        timestamptz NOT NULL,
    approved_by                    uuid,
    approved_at                    timestamptz,
    status                         text NOT NULL DEFAULT 'Requested',
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT work_schedule_pkey PRIMARY KEY (work_schedule_id),
    CONSTRAINT work_schedule_entry_type_ck CHECK (entry_type IN ('Shift', 'OnCall', 'Leave')),
    CONSTRAINT work_schedule_leave_type_ck CHECK (leave_type IN ('Planned', 'Unplanned', 'Training', 'Other')),
    CONSTRAINT work_schedule_version_ck CHECK (version >= 1),
    CONSTRAINT work_schedule_tenant_identity_uq UNIQUE (tenant_id, work_schedule_id),
    CONSTRAINT work_schedule_status_known CHECK (status IN ('Requested', 'Draft', 'Published', 'Approved', 'Rejected', 'Cancelled')),
    CONSTRAINT work_schedule_range_forward CHECK (ends_at > starts_at),
    CONSTRAINT work_schedule_leave_typed CHECK ((entry_type = 'Leave') = (leave_type IS NOT NULL))
);
COMMENT ON TABLE workforce.work_schedule IS 'Everything that decides whether a person can be booked: shifts, on-call and leave. [§53.2 availability]';

